select sf.File_MD5_Code as fileMd5Code, ar.ad_id as adId, af.* from Archive_File af left join Sys_FileAnnex sf on sf.file_id=af.Af_Annex_Id left join Archive ar on ar.Ap_Id=af.Ap_Id where
sf.File_MD5_Code is not null and ar.Ad_Id in
#{id}
and ar.P_Id=#{pid}

